46	const ACTIVE_DEFAULT_SCOPE = {
47	  name: "interactiveDefault",
48	  sourceKinds: null,
49	  meaning: "app-server default interactive source scope",
50	};
51	
52	const ACTIVE_ARCHIVE_SCOPE = {
