65	function liveLeaseFromRow(row, endpoint, maxAgeMs) {
66	  const threadID = row?.id;
67	  if (!threadID) {
68	    return null;
69	  }
70	  const status = normalizedStatus(row);
71	  const validationAtMs = Date.now();
72	  return {
73	    threadID,
74	    endpointLabel: endpoint?.label || endpoint?.url || null,
75	    endpointUrl: endpoint?.url || null,
76	    backendSessionID: row?.sessionId || threadID,
77	    status,
78	    waitingState: status === "needsApproval" || status === "needsInput" ? status : null,
79	    commandCapability: false,
80	    validationAtMs,
81	    expiresAtMs: validationAtMs + maxAgeMs,
82	  };
83	}
