85	class StateReconciler {
86	  constructor({
87	    engine,
88	    intervalMs = RELAY_STATE_RECONCILE_INTERVAL_MS,
89	    debounceMs = RELAY_STATE_RECONCILE_DEBOUNCE_MS,
90	  }) {
91	    this.engine = engine;
92	    this.intervalMs = intervalMs;
93	    this.debounceMs = debounceMs;
94	    this.timer = null;
95	    this.debounceTimer = null;
96	    this.inFlight = null;
97	  }
98	
99	  start() {
100	    if (this.timer) {
101	      return;
102	    }
103	    this.schedule({ reason: "boot", immediate: false });
104	    this.timer = setInterval(() => {
105	      this.schedule({ reason: "periodic", immediate: false });
106	    }, this.intervalMs);
107	    this.timer.unref?.();
108	  }
109	
110	  async stop() {
111	    if (this.timer) {
112	      clearInterval(this.timer);
113	      this.timer = null;
114	    }
115	    if (this.debounceTimer) {
116	      clearTimeout(this.debounceTimer);
117	      this.debounceTimer = null;
118	    }
119	    if (this.inFlight) {
120	      await this.inFlight.catch(() => null);
121	    }
122	  }
123	
124	  schedule({ reason, immediate = false } = {}) {
125	    if (immediate) {
126	      if (this.debounceTimer) {
127	        clearTimeout(this.debounceTimer);
128	        this.debounceTimer = null;
129	      }
130	      return this.run(reason || "manual");
131	    }
132	    if (this.debounceTimer) {
133	      clearTimeout(this.debounceTimer);
134	    }
135	    this.debounceTimer = setTimeout(() => {
136	      this.debounceTimer = null;
137	      this.run(reason || "debounced").catch((error) => {
138	        this.engine.logger?.warn?.("state.reconcile_failed", { reason, error });
139	      });
140	    }, this.debounceMs);
141	    this.debounceTimer.unref?.();
142	    return Promise.resolve(null);
143	  }
144	
145	  async run(reason = "manual") {
146	    if (this.inFlight) {
147	      return this.inFlight;
148	    }
149	    this.inFlight = this.engine.reconcileDock({ reason }).finally(() => {
150	      this.inFlight = null;
151	    });
152	    return this.inFlight;
153	  }
154	}
