156	class RelayStateEngine {
157	  constructor(config, options = {}) {
158	    this.config = config;
159	    this.logger = config.logger;
160	    this.store = options.store || relayStateStoreForConfig(config);
161	    this.reconciler = new StateReconciler({
162	      engine: this,
163	      intervalMs: config.relayStateReconcileIntervalMs || RELAY_STATE_RECONCILE_INTERVAL_MS,
164	      debounceMs: config.relayStateReconcileDebounceMs || RELAY_STATE_RECONCILE_DEBOUNCE_MS,
165	    });
166	    this.subscriptions = new StateSubscriptionHub({
167	      store: this.store,
168	      snapshotForView: (view, params) => this.snapshotForView(view, params),
169	      logger: this.logger,
170	      snapshotSoftLimitBytes: config.relayStateSnapshotSoftLimitBytes
171	        || RELAY_STATE_SNAPSHOT_SOFT_LIMIT_BYTES,
172	    });
173	    this.ingestor = new NotificationIngestor({
174	      store: this.store,
175	      hostId: config.hostId,
176	      scheduleReconciliation: (request) => this.scheduleReconciliation(request),
177	      logger: this.logger,
178	    });
179	    this.liveLeaseExpiryTimer = null;
180	    this.started = false;
181	  }
182	
183	  start() {
184	    if (this.started) {
185	      return;
186	    }
187	    this.started = true;
188	    this.reconciler.start();
189	  }
190	
191	  async close() {
192	    if (this.liveLeaseExpiryTimer) {
193	      clearTimeout(this.liveLeaseExpiryTimer);
194	      this.liveLeaseExpiryTimer = null;
195	    }
196	    await this.reconciler.stop();
197	    this.store.close();
198	  }
199	
200	  scheduleReconciliation(request = {}) {
201	    return this.reconciler.schedule(request);
202	  }
203	
204	  scheduleLiveLeaseExpiryReconciliation(hostID) {
205	    if (this.liveLeaseExpiryTimer) {
206	      clearTimeout(this.liveLeaseExpiryTimer);
207	      this.liveLeaseExpiryTimer = null;
208	    }
209	    const expiresAtMs = this.store.nextUnpublishedLiveLeaseExpiryMs(hostID);
210	    if (!expiresAtMs) {
211	      return;
212	    }
213	    const delayMs = Math.max(0, expiresAtMs - Date.now() + 1);
214	    this.liveLeaseExpiryTimer = setTimeout(() => {
215	      this.liveLeaseExpiryTimer = null;
216	      this.reconciler.schedule({ reason: "live-lease-expiry", immediate: true }).catch((error) => {
217	        this.logger?.warn?.("state.reconcile_failed", {
218	          reason: "live-lease-expiry",
219	          error,
220	        });
221	      });
222	    }, delayMs);
223	    this.liveLeaseExpiryTimer.unref?.();
224	  }
225	
226	  shouldReconcileAfterResponse() {
227	    const host = publicHostFromConfig(this.config);
228	    const counts = this.store.stateCounts();
229	    const freshness = this.store.freshnessForHost(host.id);
230	    const totalRows = this.store.listDockCards({ hostID: host.id, offset: 0, limit: 0 }).totalRows;
231	    return Number(totalRows || 0) === 0
232	      || Number(counts.incomplete || 0) > 0
233	      || freshness.status !== "fresh";
234	  }
235	
236	  scheduleReconciliationAfterResponse(reason, { force = false } = {}) {
237	    if (!force && !this.shouldReconcileAfterResponse()) {
238	      this.logger?.debug?.("state.reconcile_skipped", {
239	        reason,
240	        freshness: "fresh",
241	      });
242	      return;
243	    }
244	    const timer = setImmediate(() => {
245	      this.reconciler.schedule({ reason, immediate: true }).catch((error) => {
246	        this.logger?.warn?.("state.reconcile_failed", { reason, error });
247	      });
248	    });
249	    timer.unref?.();
250	  }
