252	  async reconcileDock({ reason = "manual" } = {}) {
253	    const host = publicHostFromConfig(this.config);
254	    try {
255	      const baseParams = {
256	        archived: false,
257	        limit: THREAD_LIST_MAX_LIMIT,
258	        sortKey: "updated_at",
259	        sortDirection: "desc",
260	        modelProviders: [],
261	      };
262	      const previousDockCards = this.store.listDockCards({ hostID: host.id }).cards;
263	      const [liveRows, defaultScope] = await Promise.all([
264	        this.refreshLiveLeases(),
265	        drainThreadListScope(this.config, baseParams, ACTIVE_ARCHIVE_SCOPE, ACTIVE_DEFAULT_SCOPE),
266	      ]);
267	      const interactiveRows = defaultScope.rows.map((row) => row.thread).filter(Boolean);
268	      const { acceptedRows, rejectedCounts, validationFailures } = await enrichHumanStartedRows(
269	        this.config,
270	        interactiveRows,
271	        { route: "dock_reconcile" },
272	      );
273	      const supplements = await readSessionIndexHumanStartedSupplements(this.config, acceptedRows, {
274	        route: "dock_reconcile",
275	        params: baseParams,
276	        limit: baseParams.limit,
277	      });
278	      for (const [rejectedReason, count] of Object.entries(supplements.rejectedCounts)) {
279	        rejectedCounts[rejectedReason] = Number(rejectedCounts[rejectedReason] || 0) + Number(count || 0);
280	      }
281	      const appRows = mergeHumanStartedRowsWithSupplements(acceptedRows, supplements.acceptedRows);
282	      const orderedRows = orderedDockRows([], appRows, liveRows);
283	      const cards = orderedRows
284	        .map(({ row, lane }, index) => normalizeThread(row, host, lane, {
285	          archiveState: "active",
286	          orderKey: dockOrderKey(index, row?.id || ""),
287	        }))
288	        .filter(Boolean);
289	      const totalValidationFailures = validationFailures + supplements.validationFailures;
290	      const complete = defaultScope.complete && totalValidationFailures === 0;
291	      const reconciliationScope = complete
292	        ? defaultScope
293	        : {
294	          ...defaultScope,
295	          complete: false,
296	          error: defaultScope.error || "human-started thread validation failed",
297	        };
298	      const cleanup = this.store.deleteRejectedThreadCards(host.id);
299	      const leaseCleanup = this.store.deleteRejectedLiveLeases(host.id);
300	      const result = this.store.applyDockReconciliation({
301	        host,
302	        cards,
303	        scopes: [reconciliationScope],
304	        complete,
305	        error: reconciliationScope.error || null,
306	        previousCards: previousDockCards,
307	      });
308	      const freshness = this.store.freshnessForHost(host.id);
309	      const totalRows = this.store.listDockCards({ hostID: host.id }).totalRows;
310	      const deltaCarriesEveryRow = complete
311	        && Number(result.deleteCardIDs?.length || 0) === 0
312	        && Number(result.upsertCards?.length || 0) === Number(totalRows || 0);
313	      await this.subscriptions.publishDelta(this.subscriptions.cardDelta({
314	        view: DOCK_VIEW,
315	        baseSeq: Math.max(0, Number(result.seq) - 1),
316	        seq: result.seq,
317	        freshness,
318	        upsertHosts: [host],
319	        upsertCards: result.upsertCards,
320	        deleteCardIDs: result.deleteCardIDs,
321	        totalRows,
322	        complete: deltaCarriesEveryRow ? true : undefined,
323	      }));
324	      if (complete) {
325	        this.logger?.info?.("state.reconcile_succeeded", {
326	          reason,
327	          hostId: host.id,
328	          rows: cards.length,
329	          rejectedCounts,
330	          validationFailures: totalValidationFailures,
331	          supplementedRows: supplements.acceptedRows.length,
332	          deletedRejectedCards: cleanup.deleted,
333	          deletedRejectedLiveLeases: leaseCleanup.deleted,
334	          seq: result.seq,
335	        });
336	      } else {
337	        this.logger?.warn?.("state.reconcile_incomplete", {
338	          reason,
339	          hostId: host.id,
340	          rows: cards.length,
341	          seq: result.seq,
342	          rejectedCounts,
343	          validationFailures: totalValidationFailures,
344	          supplementedRows: supplements.acceptedRows.length,
345	          deletedRejectedCards: cleanup.deleted,
346	          deletedRejectedLiveLeases: leaseCleanup.deleted,
347	          error: reconciliationScope.error || null,
348	        });
349	      }
350	      this.scheduleLiveLeaseExpiryReconciliation(host.id);
351	      return result;
352	    } catch (error) {
353	      this.store.upsertHost(host);
354	      this.store.markScopeStale(host.id, "active:interactiveDefault", error);
355	      const seq = this.store.currentSeq();
356	      const totalRows = this.store.listDockCards({ hostID: host.id }).totalRows;
357	      await this.subscriptions.publishDelta(this.subscriptions.cardDelta({
358	        view: DOCK_VIEW,
359	        baseSeq: Math.max(0, seq - 1),
360	        seq,
361	        freshness: this.store.freshnessForHost(host.id),
362	        totalRows,
363	        complete: false,
364	      }));
365	      this.logger?.warn?.("state.reconcile_failed", {
366	        reason,
367	        hostId: host.id,
368	        error,
369	      });
370	      this.scheduleLiveLeaseExpiryReconciliation(host.id);
371	      return { seq, upsertCards: [], deleteCardIDs: [], error };
372	    }
373	  }
