375	  async reconcileArchive({ reason = "manual" } = {}) {
376	    const host = publicHostFromConfig(this.config);
377	    try {
378	      const baseParams = {
379	        archived: true,
380	        limit: THREAD_LIST_MAX_LIMIT,
381	        sortKey: "updated_at",
382	        sortDirection: "desc",
383	        modelProviders: [],
384	      };
385	      const previousArchiveCards = this.store.listArchiveCards({ hostID: host.id }).cards;
386	      const history = await aggregateThreadList(this.config, baseParams);
387	      const rows = Array.isArray(history?.data) ? history.data : [];
388	      const cards = rows
389	        .map((row) => normalizeThread(row, host, "human", {
390	          archiveState: "archived",
391	        }))
392	        .filter(Boolean);
393	      const result = this.store.applyArchiveReconciliation({
394	        host,
395	        cards,
396	        complete: true,
397	        previousCards: previousArchiveCards,
398	      });
399	      const freshness = this.store.freshnessForHost(host.id);
400	      const totalRows = this.store.listArchiveCards({ hostID: host.id }).totalRows;
401	      await this.subscriptions.publishDelta(this.subscriptions.cardDelta({
402	        view: ARCHIVE_VIEW,
403	        baseSeq: Math.max(0, Number(result.seq) - 1),
404	        seq: result.seq,
405	        freshness,
406	        upsertHosts: [host],
407	        upsertCards: result.upsertCards,
408	        deleteCardIDs: result.deleteCardIDs,
409	        totalRows,
410	        complete: true,
411	      }));
412	      this.logger?.info?.("state.archive_reconcile_succeeded", {
413	        reason,
414	        hostId: host.id,
415	        rows: cards.length,
416	        seq: result.seq,
417	      });
418	      return result;
419	    } catch (error) {
420	      this.store.upsertHost(host);
421	      this.store.markScopeStale(host.id, "archived:interactiveDefault", error);
422	      const seq = this.store.currentSeq();
423	      const totalRows = this.store.listArchiveCards({ hostID: host.id }).totalRows;
424	      await this.subscriptions.publishDelta(this.subscriptions.cardDelta({
425	        view: ARCHIVE_VIEW,
426	        baseSeq: Math.max(0, seq - 1),
427	        seq,
428	        freshness: this.store.freshnessForHost(host.id),
429	        totalRows,
430	        complete: false,
431	      }));
432	      this.logger?.warn?.("state.archive_reconcile_failed", {
433	        reason,
434	        hostId: host.id,
435	        error,
436	      });
437	      return { seq, upsertCards: [], deleteCardIDs: [], error };
438	    }
439	  }
