441	  async refreshLiveLeases() {
442	    const host = publicHostFromConfig(this.config);
443	    const endpoints = configuredLiveEndpointsForConfig(this.config, { includeHistory: true });
444	    const live = await collectLiveRows({
445	      logger: this.logger,
446	      pool: this.config.upstreamPool || null,
447	      endpoints,
448	      excludeURLs: [],
449	    });
450	    const endpointsByUrl = new Map(endpoints.map((endpoint) => [endpoint.url, endpoint]));
451	    const acceptedRows = [];
452	    for (const row of live.rows || []) {
453	      if (!isHumanStartedThread(row)) {
454	        continue;
455	      }
456	      const endpoint = endpointsByUrl.get(row?.dockRelaySource?.url) || row?.dockRelaySource || null;
457	      const lease = liveLeaseFromRow(
458	        row,
459	        endpoint,
460	        this.config.liveStatusMaxAgeMs || 5_000,
461	      );
462	      if (lease) {
463	        this.store.upsertLiveLease(host.id, lease);
464	        acceptedRows.push(row);
465	      }
466	    }
467	    this.store.deleteRejectedLiveLeases(host.id);
468	    return acceptedRows;
469	  }
