471	  snapshotForView(view, {
472	    epoch,
473	    offset = 0,
474	    limit = RELAY_STATE_DOCK_WINDOW_SIZE,
475	    softLimitBytes = RELAY_STATE_SNAPSHOT_SOFT_LIMIT_BYTES,
476	  } = {}) {
477	    if (view === ARCHIVE_VIEW) {
478	      return this.snapshotArchive({ epoch, offset, limit, softLimitBytes });
479	    }
480	    return this.snapshotDock({ epoch, offset, limit, softLimitBytes });
481	  }
482	
483	  snapshotDock({
484	    epoch = this.subscriptions.epoch,
485	    offset = 0,
486	    limit = RELAY_STATE_DOCK_WINDOW_SIZE,
487	    softLimitBytes = RELAY_STATE_SNAPSHOT_SOFT_LIMIT_BYTES,
488	  } = {}) {
489	    const host = publicHostFromConfig(this.config);
490	    const totalRows = this.store.listDockCards({ hostID: host.id, offset: 0, limit: 0 }).totalRows;
491	    if (totalRows === 0) {
492	      return this.makeSnapshot({
493	        view: DOCK_VIEW,
494	        epoch,
495	        complete: true,
496	        totalRows: 0,
497	        window: buildWindow({ offset: 0, limit: 0, rowCount: 0, totalRows: 0 }),
498	        cards: [],
499	        freshness: this.store.freshnessForHost(host.id),
500	      });
501	    }
502	
503	    let windowLimit = Math.max(1, Math.min(Number(limit || 1), totalRows));
504	    let bounded = this.store.listDockCards({ hostID: host.id, offset, limit: windowLimit });
505	    let window = buildWindow({
506	      offset,
507	      limit: windowLimit,
508	      rowCount: bounded.cards.length,
509	      totalRows: bounded.totalRows,
510	    });
511	    let snapshot = this.makeSnapshot({
512	      view: DOCK_VIEW,
513	      epoch,
514	      complete: offset + bounded.cards.length >= bounded.totalRows,
515	      totalRows: bounded.totalRows,
516	      window,
517	      cards: bounded.cards,
518	      freshness: this.store.freshnessForHost(host.id),
519	    });
520	
521	    while (estimateJSONBytes(snapshot) > softLimitBytes && windowLimit > 1) {
522	      windowLimit = Math.max(1, Math.floor(windowLimit / 2));
523	      bounded = this.store.listDockCards({ hostID: host.id, offset, limit: windowLimit });
524	      window = buildWindow({
525	        offset,
526	        limit: windowLimit,
527	        rowCount: bounded.cards.length,
528	        totalRows: bounded.totalRows,
529	      });
530	      snapshot = this.makeSnapshot({
531	        view: DOCK_VIEW,
532	        epoch,
533	        complete: offset + bounded.cards.length >= bounded.totalRows,
534	        totalRows: bounded.totalRows,
535	        window,
536	        cards: bounded.cards,
537	        freshness: this.store.freshnessForHost(host.id),
538	      });
539	    }
540	
541	    return this.makeSnapshot({
542	      view: DOCK_VIEW,
543	      epoch,
544	      complete: offset + bounded.cards.length >= bounded.totalRows,
545	      totalRows: bounded.totalRows,
546	      window,
547	      cards: bounded.cards,
548	      freshness: this.store.freshnessForHost(host.id),
549	    });
550	  }
551	
552	  snapshotArchive({
553	    epoch = this.subscriptions.epoch,
554	    offset = 0,
555	    limit = RELAY_STATE_DOCK_WINDOW_SIZE,
556	  } = {}) {
557	    const host = publicHostFromConfig(this.config);
558	    const result = this.store.listArchiveCards({ hostID: host.id, offset, limit });
559	    return this.makeSnapshot({
560	      view: ARCHIVE_VIEW,
561	      epoch,
562	      complete: offset + result.cards.length >= result.totalRows,
563	      totalRows: result.totalRows,
564	      window: buildWindow({
565	        offset,
566	        limit,
567	        rowCount: result.cards.length,
568	        totalRows: result.totalRows,
569	      }),
570	      cards: result.cards,
571	      freshness: this.store.freshnessForHost(host.id),
572	    });
573	  }
574	
575	  makeSnapshot({
576	    view,
577	    epoch,
578	    complete,
579	    totalRows,
580	    window,
581	    cards,
582	    freshness,
583	  }) {
584	    return {
585	      kind: "snapshot",
586	      schemaVersion: 2,
587	      epoch,
588	      baseSeq: null,
589	      seq: this.store.currentSeq(),
590	      stateGeneration: this.store.currentSeq(),
591	      view,
592	      complete,
593	      totalRows,
594	      window,
595	      asOf: nowISOString(),
596	      visibility: appFacingHumanStartedVisibility(),
597	      freshness,
598	      hosts: this.store.hostRows(),
599	      cards,
600	    };
601	  }
