603	  async subscribeDock({ session, downstreamWs, sendJson }) {
604	    return this.subscribeCardView({
605	      view: DOCK_VIEW,
606	      updateMethod: "dock/update",
607	      subscribeReason: "dock/subscribe",
608	      updateReason: "dock/update",
609	      unsubscribeKey: "dockUnsubscribe",
610	      session,
611	      downstreamWs,
612	      sendJson,
613	      after: () => this.scheduleReconciliationAfterResponse("dock/subscribe"),
614	    });
615	  }
616	
617	  async subscribeArchive({ session, downstreamWs, sendJson }) {
618	    return this.subscribeCardView({
619	      view: ARCHIVE_VIEW,
620	      updateMethod: "archive/update",
621	      subscribeReason: "archive/subscribe",
622	      updateReason: "archive/update",
623	      unsubscribeKey: "archiveUnsubscribe",
624	      session,
625	      downstreamWs,
626	      sendJson,
627	      after: () => this.scheduleArchiveReconciliationAfterResponse("archive/subscribe"),
628	    });
629	  }
630	
631	  async subscribeCardView({
632	    view,
633	    updateMethod,
634	    subscribeReason,
635	    updateReason,
636	    unsubscribeKey,
637	    session,
638	    downstreamWs,
