535	  applyDockReconciliation({ host, cards, scopes = [], complete = true, error = null, previousCards = null }) {
536	    const atMs = nowMs();
537	    const at = new Date(atMs).toISOString();
538	    return this.transaction(() => {
539	      this.upsertHost(host, at);
540	      const previousRows = Array.isArray(previousCards)
541	        ? previousCards
542	        : this.listDockCards({ hostID: host.id }).cards;
543	      const previousByID = new Map(previousRows.map((row) => [row.id, row]));
544	      const existingRows = this.db.prepare(`
545	        SELECT thread_id, archive_state, freshness_status, updated_at
546	        FROM threads
547	        WHERE host_id = ?
548	      `).all(host.id);
549	      const existingByThreadID = new Map(existingRows.map((row) => [row.thread_id, row]));
550	      const leaseRows = this.db.prepare(`
551	        SELECT thread_id, backend_session_id AS lease_backend_session_id,
552	               status AS lease_status, expires_at_ms, expired_published_at
553	        FROM live_leases
554	        WHERE host_id = ?
555	      `).all(host.id);
556	      const leasesByThreadID = new Map(leaseRows.map((row) => [row.thread_id, row]));
557	      const currentMs = nowMs();
558	      const projectCardForClient = (card) => {
559	        const lease = leasesByThreadID.get(card.threadID);
560	        if (!lease) {
561	          return card;
562	        }
563	        return applyLeaseToCard(card, {
564	          backend_session_id: lease.lease_backend_session_id,
565	          status: lease.lease_status,
566	          expires_at_ms: lease.expires_at_ms,
567	        }, currentMs);
568	      };
569	      const nextByID = new Map();
570	      const upsertCards = [];
571	      const deleteCardIDs = [];
572	
573	      cards.forEach((card) => {
574	        const existing = existingByThreadID.get(card.threadID);
575	        if (isFreshLocalArchiveMutation(existing, atMs)) {
576	          return;
577	        }
578	        const cardWithOrder = {
579	          ...card,
580	          orderKey: card.orderKey || dockOrderKey(index, card.threadID),
581	          archiveState: "active",
582	        };
583	        nextByID.set(cardWithOrder.id, cardWithOrder);
584	        const previous = previousByID.get(cardWithOrder.id);
585	        const clientCard = projectCardForClient(cardWithOrder);
586	        const lease = leasesByThreadID.get(cardWithOrder.threadID);
587	        const expiredLeaseNeedsPublish = isLeaseExpired(lease, currentMs) && !lease.expired_published_at;
588	        if (expiredLeaseNeedsPublish || sortedJSONString(previous) !== sortedJSONString(clientCard)) {
589	          upsertCards.push(clientCard);
590	        }
591	        this.upsertThreadCard(host.id, cardWithOrder, {
592	          archiveState: "active",
593	          activeScopePresent: true,
594	          at,
595	        });
596	        if (expiredLeaseNeedsPublish) {
597	          this.markLiveLeaseExpiryPublished(host.id, cardWithOrder.threadID, at);
598	        }
599	      });
600	
601	      if (complete) {
602	        for (const previous of previousRows) {
603	          if (!nextByID.has(previous.id)) {
604	            deleteCardIDs.push(previous.id);
605	            this.markThreadInactive(host.id, previous.threadID, at);
606	          }
607	        }
608	      }
609	
610	      for (const scope of scopes) {
611	        this.recordSyncScope(host.id, scope, at);
612	      }
613	      if (scopes.length === 0) {
614	        this.recordSyncScope(host.id, {
615	          name: "active:interactiveDefault",
616	          archived: false,
617	          sourceScope: "interactiveDefault",
618	          complete,
619	          error,
620	        }, at);
621	      }
622	
623	      const seq = this.recordChange({
624	        view: DOCK_VIEW,
625	        hostID: host.id,
626	        changeType: "dock-reconcile",
627	        payload: {
628	          upsertCount: upsertCards.length,
629	          deleteCount: deleteCardIDs.length,
630	          complete,
631	        },
632	        at,
633	      });
634	      this.pruneChanges();
635	      return { seq, upsertCards, deleteCardIDs };
636	    });
637	  }
