3	enum ThreadCardTableResyncReason: String, Equatable, Sendable {
4	    case schemaMismatch
5	    case streamContract
6	    case epochMismatch
7	    case sequenceGap
8	}
9	
10	enum ThreadCardTableApplyResult: Equatable, Sendable {
11	    case applied
12	    case needsResync(ThreadCardTableResyncReason)
13	}
14	
15	struct ThreadCardTable: Equatable, Sendable {
16	    private struct HostStreamState: Equatable, Sendable {
17	        var epoch: String?
18	        var seq: Int64
19	        var status: DockHostLoadStatus
20	        var freshness: DockStreamFreshnessDTO?
21	        var complete: Bool
22	        var totalRows: Int?
23	        var window: DockStreamWindowDTO?
24	        var streamHosts: [DockStreamHostDTO]
25	        var cardsByID: [String: DockThreadCardDTO]
26	
27	        init(status: DockHostLoadStatus = .checking) {
28	            self.epoch = nil
29	            self.seq = 0
30	            self.status = status
31	            self.freshness = nil
32	            self.complete = false
33	            self.totalRows = nil
34	            self.window = nil
35	            self.streamHosts = []
36	            self.cardsByID = [:]
37	        }
38	    }
39	
40	    private var statesByHostID: [String: HostStreamState] = [:]
41	
42	    mutating func reset(hosts: [DockHostConfiguration]) {
43	        statesByHostID = Dictionary(
44	            uniqueKeysWithValues: hosts.map { host in
45	                (host.id, HostStreamState())
46	            }
47	        )
48	    }
49	
50	    mutating func ensureHosts(_ hosts: [DockHostConfiguration]) {
51	        let validHostIDs = Set(hosts.map(\.id))
52	        statesByHostID = statesByHostID.filter { validHostIDs.contains($0.key) }
53	        for host in hosts where statesByHostID[host.id] == nil {
54	            statesByHostID[host.id] = HostStreamState()
55	        }
56	    }
57	
58	    mutating func markChecking(host: DockHostConfiguration) {
59	        var state = statesByHostID[host.id] ?? HostStreamState()
60	        let rowCount = state.cardsByID.count
61	        state.status = rowCount > 0
62	            ? .partial(rowCount: rowCount, message: "Reconnecting")
63	            : .checking
64	        statesByHostID[host.id] = state
65	    }
66	
67	    mutating func markFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) {
68	        var state = statesByHostID[host.id] ?? HostStreamState()
69	        let message = failure.localizedDescription
70	        let rowCount = state.cardsByID.count
71	        switch failure {
72	        case .offline:
73	            state.status = rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
74	            state.freshness = DockStreamFreshnessDTO(status: .offline, lastError: message)
75	        case .error:
76	            state.status = rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
77	            state.freshness = DockStreamFreshnessDTO(status: .error, lastError: message)
78	        }
79	        statesByHostID[host.id] = state
80	    }
81	
82	    mutating func applySnapshot(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
83	        guard acceptsSchemaVersion(update.schemaVersion) else {
84	            return .needsResync(.schemaMismatch)
85	        }
86	        guard acceptsStreamContract(update) else {
87	            return .needsResync(.streamContract)
88	        }
89	
90	        var state = statesByHostID[host.id] ?? HostStreamState()
91	        state.epoch = update.epoch
92	        state.seq = update.seq
93	        state.freshness = update.freshness
94	        state.complete = update.complete ?? false
95	        state.totalRows = update.totalRows
96	        state.window = update.window
97	        state.streamHosts = update.hosts ?? []
98	        state.cardsByID = Dictionary(
99	            uniqueKeysWithValues: (update.cards ?? [])
100	                .filter(\.isAppFacingHumanThreadCard)
101	                .map { card in
102	                    (card.id, card)
103	                }
104	        )
105	        state.status = hostStatus(
106	            freshness: update.freshness,
107	            rowCount: state.cardsByID.count,
108	            complete: state.complete,
109	            totalRows: state.totalRows
110	        )
111	        statesByHostID[host.id] = state
112	        return .applied
113	    }
114	
115	    mutating func applyUpdate(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
116	        guard update.kind != .snapshot else {
117	            return applySnapshot(update, host: host)
118	        }
119	
120	        guard acceptsSchemaVersion(update.schemaVersion) else {
121	            return .needsResync(.schemaMismatch)
122	        }
123	        guard acceptsStreamContract(update) else {
124	            return .needsResync(.streamContract)
125	        }
126	
127	        guard var state = statesByHostID[host.id],
128	              state.epoch == update.epoch else {
129	            return .needsResync(.epochMismatch)
130	        }
131	
132	        switch update.kind {
133	        case .heartbeat:
134	            guard state.seq == update.seq else {
135	                return .needsResync(.sequenceGap)
136	            }
137	        case .delta:
138	            guard update.baseSeq == state.seq else {
139	                return .needsResync(.sequenceGap)
