195	actor LoaderBackedThreadCardStreamConnection: ThreadCardStreamConnection {
196	    private let host: DockHostConfiguration
197	    private let loader: any ThreadCardFixtureLoading
198	    private let view: ThreadCardStreamView
199	    private var seq: Int64 = 0
200	
201	    init(host: DockHostConfiguration, loader: any ThreadCardFixtureLoading, view: ThreadCardStreamView) {
202	        self.host = host
203	        self.loader = loader
204	        self.view = view
205	    }
206	
207	    func subscribe() async throws -> ThreadCardStreamUpdateDTO {
208	        try await snapshot()
209	    }
210	
211	    func resync() async throws -> ThreadCardStreamUpdateDTO {
212	        try await snapshot()
213	    }
214	
215	    nonisolated func updates() -> AsyncThrowingStream<ThreadCardStreamUpdateDTO, Error> {
216	        AsyncThrowingStream { _ in }
217	    }
218	
219	    func close() async {}
220	
221	    private func snapshot() async throws -> ThreadCardStreamUpdateDTO {
222	        seq += 1
223	        if view == .archive {
224	            let result = try await loader.loadFixtures(for: host, query: .archivedHuman)
225	            let cards = result.fixtures.map {
226	                streamCard(from: $0, archiveState: .archived)
227	            }
228	            return update(cards: cards, freshness: DockStreamFreshnessDTO(status: .fresh))
229	        }
230	
231	        let scopedResults = await loadScopes()
232	        let successes = scopedResults.compactMap { scope, result -> (ThreadCardFixtureScope, ThreadCardFixtureResult)? in
233	            if case .success(let value) = result {
234	                return (scope, value)
235	            }
236	            return nil
237	        }
238	        let failures = scopedResults.compactMap { scope, result -> (ThreadCardFixtureScope, DockRequestFailure)? in
239	            if case .failure(let value) = result {
240	                return (scope, value)
241	            }
242	            return nil
243	        }
244	
245	        guard !successes.isEmpty else {
246	            throw failures.first?.1 ?? DockRequestFailure.error("No stream rows loaded")
247	        }
248	
249	        let fixtures = deduplicated(successes.flatMap { scope, result in
250	            result.fixtures.map { summary in
251	                (scope, summary)
252	            }
253	        })
254	        let freshness: DockStreamFreshnessDTO
255	        if failures.isEmpty {
256	            freshness = DockStreamFreshnessDTO(status: .fresh)
257	        } else {
258	            let message = failures.map { scope, failure in
259	                "\(scope.label): \(failure.localizedDescription)"
260	            }.joined(separator: "; ")
261	            freshness = DockStreamFreshnessDTO(status: .stale, lastError: message)
262	        }
263	
264	        return update(
265	            cards: fixtures.map { streamCard(from: $0) },
266	            freshness: freshness
267	        )
268	    }
269	
270	    private func update(
271	        cards: [DockThreadCardDTO],
272	        freshness: DockStreamFreshnessDTO
273	    ) -> ThreadCardStreamUpdateDTO {
274	        let logicalHostID = cards.first?.logicalHostID ?? host.id
275	        let hostDisplayName = cards.first?.hostDisplayName ?? host.displayName
276	        return ThreadCardStreamUpdateDTO(
277	            kind: .snapshot,
278	            schemaVersion: CodexDockConstants.Dock.streamSchemaVersion,
279	            view: view,
280	            complete: true,
281	            totalRows: cards.count,
282	            window: DockStreamWindowDTO(offset: 0, limit: cards.count, rowCount: cards.count),
283	            stateGeneration: seq,
284	            epoch: host.id,
285	            seq: seq,
286	            freshness: freshness,
287	            hosts: [
288	                DockStreamHostDTO(
289	                    id: logicalHostID,
290	                    logicalHostID: logicalHostID,
291	                    displayName: hostDisplayName,
292	                    endpoint: host.endpoint.displayEndpoint
293	                )
294	            ],
295	            cards: cards
296	        )
297	    }
298	
299	    private func loadScopes() async -> [(ThreadCardFixtureScope, Result<ThreadCardFixtureResult, DockRequestFailure>)] {
300	        let host = self.host
301	        let loader = self.loader
302	        return await withTaskGroup(of: (ThreadCardFixtureScope, Result<ThreadCardFixtureResult, DockRequestFailure>).self) { group in
303	            for scope in ThreadCardFixtureScope.allCases {
304	                group.addTask {
305	                    do {
306	                        let result = try await loader.loadFixtures(for: host, query: scope.query)
307	                        return (scope, .success(result))
308	                    } catch {
309	                        if let failure = error as? DockRequestFailure {
310	                            return (scope, .failure(failure))
311	                        }
312	                        return (scope, .failure(.error(error.localizedDescription)))
313	                    }
314	                }
315	            }
316	            var results: [(ThreadCardFixtureScope, Result<ThreadCardFixtureResult, DockRequestFailure>)] = []
317	            for await result in group {
318	                results.append(result)
319	            }
320	            return results.sorted { lhs, rhs in
321	                let lhsIndex = ThreadCardFixtureScope.allCases.firstIndex(of: lhs.0) ?? Int.max
322	                let rhsIndex = ThreadCardFixtureScope.allCases.firstIndex(of: rhs.0) ?? Int.max
323	                return lhsIndex < rhsIndex
324	            }
325	        }
326	    }
