328	    private func deduplicated(_ fixtures: [(ThreadCardFixtureScope, ThreadCardFixtureSummary)]) -> [ThreadCardFixtureSummary] {
329	        var orderedIDs: [HostScopedThreadID] = []
330	        var summariesByID: [HostScopedThreadID: ThreadCardFixtureSummary] = [:]
331	        for (scope, summary) in fixtures {
332	            if summariesByID[summary.id] == nil {
333	                orderedIDs.append(summary.id)
334	                summariesByID[summary.id] = summary
335	                continue
336	            }
337	            guard let existing = summariesByID[summary.id] else {
338	                continue
339	            }
340	            if scope == .agents || existing.origin.kind == .unknown {
341	                summariesByID[summary.id] = summary
342	            }
343	        }
344	        return orderedIDs.compactMap { summariesByID[$0] }
345	    }
