40	private struct DockCardProjectionProjector {
41	    let snapshot: DockSnapshot
42	    let options: DockProjectionOptions
43	
44	    func project() -> DockCardProjection {
45	        let searchedRows = snapshot.rows.filter(matchesSearch)
46	        let filteredIgnoringIdle = searchedRows.filter(matchesNonIdleFilters)
47	        let pinnedRows = filteredIgnoringIdle.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
48	        let hiddenIdleRows = options.filters.showsIdle
49	            ? []
50	            : filteredIgnoringIdle.filter { !$0.isPinned && $0.status == .idle }
51	        let hiddenIdleCount = hiddenIdleRows.count
52	        let bodyRows = filteredIgnoringIdle
53	            .filter { !$0.isPinned }
54	            .filter { options.filters.showsIdle || $0.status != .idle }
55	            .sorted(by: rowPrecedesByRecency)
56	        let visibleRows = (pinnedRows + bodyRows).sorted(by: rowPrecedesByRecency)
57	        let allPinnedRows = snapshot.rows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
58	        let groups = groups(for: bodyRows, hiddenIdleRows: hiddenIdleRows)
59	        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows, hiddenIdleCount: hiddenIdleCount) : nil
60	
61	        return DockCardProjection(
62	            lens: options.lens,
63	            pinnedRows: pinnedRows,
64	            allPinnedRows: allPinnedRows,
65	            pinnedSummary: DockPinnedSummary(
66	                visibleCount: pinnedRows.count,
67	                totalCount: allPinnedRows.count,
68	                hiddenByScopeCount: max(0, allPinnedRows.count - pinnedRows.count)
69	            ),
70	            rows: options.lens == .newest ? bodyRows : [],
71	            groups: groups,
72	            summary: summary(for: visibleRows),
73	            hiddenCounts: DockProjectionHiddenCounts(idle: hiddenIdleCount),
74	            availableFacets: availableFacets(),
75	            emptyReason: emptyReason,
76	            isPartial: snapshot.isPartial,
77	            checkingHostCount: snapshot.hostStates.filter { $0.status == .checking }.count
78	        )
79	    }
80	
81	    private func groups(
82	        for rows: [DockRowViewModel],
83	        hiddenIdleRows: [DockRowViewModel]
84	    ) -> [DockProjectionGroupViewModel] {
85	        switch options.lens {
86	        case .newest:
87	            return []
88	        case .host:
89	            return hostGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
90	        case .branch:
91	            return branchGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
92	        }
93	    }
