95	    private func hostGroups(
96	        for rows: [DockRowViewModel],
97	        hiddenIdleRows: [DockRowViewModel]
98	    ) -> [DockProjectionGroupViewModel] {
99	        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
100	        return snapshot.hosts.compactMap { host in
101	            if !options.filters.selectedHostIDs.isEmpty,
102	               !options.filters.selectedHostIDs.contains(host.id) {
103	                return nil
104	            }
105	
106	            let hostRows = rows
107	                .filter { rowBelongs($0, to: host.id) }
108	                .sorted(by: rowPrecedesByRecency)
109	            let hiddenIdleCount = hiddenIdleRows.filter { rowBelongs($0, to: host.id) }.count
110	            let hostState = stateByHost[host.id]
111	            let isUnavailable = hostState?.status.isUnavailable ?? false
112	            guard !hostRows.isEmpty || hiddenIdleCount > 0 || isUnavailable || hostState?.status == .checking else {
113	                return nil
114	            }
115	
116	            return DockProjectionGroupViewModel(
117	                id: "host::\(host.id)",
118	                kind: .host,
119	                title: host.displayName,
120	                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
121	                rows: hostRows,
